import { createReadStream } from 'node:fs';
import { mkdir, rm, stat, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { Readable } from 'node:stream';
import { z } from 'zod';
import type { ProviderAdapter, StorageClient } from '../types.js';

export const localConfigSchema = z.object({ root: z.string().min(1).default('data/files') });
export type LocalConfig = z.infer<typeof localConfigSchema>;

/** Keys are generated by the server; still, refuse anything that could leave the root. */
export function safeKey(key: string): string {
  if (!/^[A-Za-z0-9][A-Za-z0-9/_.=-]*$/.test(key) || key.split('/').some((part) => part === '..' || part === '')) {
    throw new Error(`Invalid storage key "${key}"`);
  }
  return key;
}

export function createLocalStorage(config: LocalConfig): StorageClient {
  const root = resolve(config.root);
  const pathOf = (key: string) => join(root, safeKey(key));
  return {
    async put(key, body) {
      const path = pathOf(key);
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, body);
    },
    async get(key) {
      const path = pathOf(key);
      const info = await stat(path).catch(() => null);
      if (!info?.isFile()) return null;
      return { body: Readable.toWeb(createReadStream(path)) as ReadableStream<Uint8Array>, size: info.size };
    },
    async head(key) {
      const info = await stat(pathOf(key)).catch(() => null);
      return info?.isFile() ? { size: info.size } : null;
    },
    async delete(key) {
      await rm(pathOf(key), { force: true });
    },
  };
}

export const localAdapter: ProviderAdapter<'storage', LocalConfig> = {
  capability: 'storage',
  kind: 'local',
  label: '本地磁盘',
  configSchema: localConfigSchema as z.ZodType<LocalConfig>,
  secretKeys: [],
  endpoints: () => null,
  create: ({ config }) => createLocalStorage(config),
  async test(client) {
    await client.put('greenhouse-check', new TextEncoder().encode('ok'), { contentType: 'text/plain' });
    await client.delete('greenhouse-check');
  },
};
